/**
 * Theme-matched weekday completion blueprints for truncated jul2026 toddler/infant plans.
 * Each missing day includes multiple complete, play-based activities (not generic filler).
 */
"use strict";

function act(category, name, objective, description, materials, setup, directions, teacherRole, learningGoals, observations, adaptations, safetyNotes) {
  return {
    activityCategory: category,
    title: name,
    objective,
    description,
    materials: Array.isArray(materials) ? materials.join("\n") : materials,
    setup,
    steps: directions.map((d, i) => `${i + 1}. ${d}`).join("\n"),
    teacherRole,
    learningGoals: Array.isArray(learningGoals) ? learningGoals : [learningGoals],
    observationOpportunities: Array.isArray(observations) ? observations.map((o) => `- ${o}`).join("\n") : observations,
    adaptations,
    safetyNotes,
  };
}

const TODDLER_DEFAULT_ADAPT = "Offer larger materials, shorter turns, and hand-over-hand support. Allow parallel play and observation first.";
const TODDLER_DEFAULT_SAFE = "Supervise closely, keep materials too large to choke on, clear walkways, and check outdoor surfaces before play.";
const INFANT_DEFAULT_ADAPT = "Adjust positioning for each infant's comfort. Offer larger graspable materials and shorter bursts of engagement.";
const INFANT_DEFAULT_SAFE = "Remain within arm's reach. Use only infant-safe materials, avoid small parts, and never leave infants unattended on elevated surfaces.";

